<script setup lang="ts">
/**
 * components/station/StationSelectionGrid.vue
 * ---------------------------------------------------------------------------
 * เนื้อหาหลักของหน้า "เลือกฐาน" (pages/stations.vue) — เดิมเคยเป็นป็อปอัพ
 * (StationUnlockModal.vue) แต่ตามสเปกล่าสุด "ห้ามใช้ Popup เป็นหน้าเลือกฐาน"
 * จึงเปลี่ยนเป็น Component เนื้อหาธรรมดา (ไม่มี UModal ห่อ) ให้หน้าเต็ม
 * pages/stations.vue เป็นคนคุม Layout/Header เอง แสดงฐานทั้งหมดตามจำนวนจริงจาก
 * Backend (ไม่ hardcode ว่ามีกี่ฐาน) พร้อมสถานะ + Progress ต่อฐาน (ดู
 * StationSelectionCard.vue)
 */
import type { StationCardState } from '~/types/stationMission'
import StationSelectionCard from './StationSelectionCard.vue'

defineProps<{
  stations: { id: string; name: string; icon: string; imageUrl?: string }[]
  cardStates: Record<string, StationCardState>
}>()

const emit = defineEmits<{
  select: [stationId: string]
}>()

/** fallback เผื่อ cardStates ไม่มี entry ของฐานนี้ (ไม่ควรเกิดขึ้นจริง — ผู้เรียก
 * สร้าง cardStates จาก stations ชุดเดียวกันเสมอ) ป้องกัน runtime error เฉย ๆ */
const EMPTY_CARD_STATE: StationCardState = {
  completedMissions: 0,
  totalMissions: 0,
  isCompleted: false,
  isAccessible: false,
}
</script>

<template>
  <div class="station-grid">
    <StationSelectionCard
      v-for="station in stations"
      :key="station.id"
      :station="station"
      :card-state="cardStates[station.id] ?? EMPTY_CARD_STATE"
      @select="emit('select', $event)"
    />
  </div>
</template>

<style scoped>
.station-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.85rem;
}
</style>
