<script setup lang="ts">
/**
 * pages/stations.vue
 * ---------------------------------------------------------------------------
 * หน้าเต็ม "เลือกฐาน" — เข้ามาหลังสแกน QR ฐานสำเร็จจาก pages/scan.vue (ดู
 * unlockStationFromScan() ที่นั้น) ตามสเปก "ห้ามใช้ Popup เป็นหน้าเลือกฐาน"
 *
 * [แก้ไข] แสดงฐานทั้งหมดตามจำนวน/ลำดับจริงจาก Backend (useAdventure().stations
 * — กรอง active + เรียง order มาให้แล้ว) ไม่ hardcode ว่ามี 4 ฐาน/id ใดบ้างอีก
 * ต่อไป Admin เพิ่มฐานใหม่ใน Backend ต้องปรากฏที่นี่ได้โดยไม่ต้องแก้โค้ด — พร้อม
 * Progress ต่อฐาน (จำนวนด่านย่อยจริงจาก Backend ดู types/mission.ts) กดเข้าได้
 * เฉพาะฐานที่ทำด่านย่อยครบแล้ว (ดูซ้ำได้เสมอ) หรือฐานที่เพิ่งได้สิทธิ์จากการสแกน
 * ล่าสุดเท่านั้น (ดู composables/useStationQuest.ts::canEnterStation)
 */
import { getStationVisual } from "~/composables/useAdventure";
import type { StationCardState } from "~/types/stationMission";
import StationSelectionGrid from "~/components/station/StationSelectionGrid.vue";

definePageMeta({ layout: "app" });
const { profile, isReady } = useRequireProfile();
const { stations, initAdventure } = useAdventure();
const { getStationCardState, initStationQuest } = useStationQuest();
// [ใหม่] ต้อง restore Cache ภารกิจ (ผูกกับ Round ปัจจุบัน) ก่อนเสมอด้วย — ไม่งั้น
// การ์ดฐานที่เคยทำภารกิจไปแล้วจะโชว์ Progress 0 ผิด ๆ ตอน Hard Refresh เข้าหน้า
// นี้ตรง ๆ (getStationCardState() ด้านบนอ่านจาก useStationMissions() ภายในเอง)
const { initStationMissions } = useStationMissions();

/** ชื่อ/ไอคอนจริงจาก stations (Admin แก้ผ่าน Backend ได้) — ไอคอนใช้ imageUrl
 * ถ้า Admin ตั้งไว้ ไม่มี -> วนไอคอน generic ตามลำดับ (getStationVisual) */
const stationList = computed(() =>
  stations.value.map((s, index) => ({
    id: s.id,
    name: s.name,
    icon: getStationVisual(index).icon,
    imageUrl: s.imageUrl,
  })),
);

const cardStates = computed<Record<string, StationCardState>>(() => {
  const map: Record<string, StationCardState> = {};
  for (const s of stations.value) map[s.id] = getStationCardState(s.id);
  return map;
});

function handleSelect(stationId: string): void {
  navigateTo(`/station/${stationId}`);
}

/** [Fix — เหตุผลเดียวกับ pages/home.vue] initStationQuest() ต้องเรียกก่อน
 * initAdventure() (Network Call) เสมอ ไม่งั้น layouts/app.vue จะซ่อน BottomNav
 * ไปชั่วคราว/ค้างนาน (hasActiveRoundTimer อ่านค่าเดียวกัน ยังไม่ถูก restore) ตอน
 * Hard Refresh หน้านี้ตรง ๆ ทั้งที่ Round จริงยังไม่จบ */
onMounted(async () => {
  await initStationQuest();
  initStationMissions();
  await initAdventure(profile.value?.memberId);
});
</script>

<template>
  <div class="page">
    <PageHeader title="เลือกฐาน" />
    <div v-if="!isReady" class="page__loading">
      <UIcon name="i-lucide-loader-2" class="page__spinner" />
    </div>
    <div v-else class="page__content">
      <p class="page__hint">แตะฐานที่ปลดล็อคเพื่อเริ่มทำภารกิจ</p>
      <StationSelectionGrid :stations="stationList" :card-states="cardStates" @select="handleSelect" />
    </div>
  </div>
</template>

<style scoped>
.page {
  display: flex;
  flex-direction: column;
  min-height: 100%;
}

.page__loading {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.page__spinner {
  width: 2.5rem;
  height: 2.5rem;
  animation: stations-spin 1s linear infinite;
  color: var(--farm-accent-dark);
}

.page__content {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding: 0.5rem 1.1rem 2rem;
}

.page__hint {
  margin: 0;
  text-align: center;
  font-size: 0.82rem;
  color: var(--farm-text-muted);
}

@keyframes stations-spin {
  to {
    transform: rotate(360deg);
  }
}
</style>
